import{_ as d,f as l,c as a,a6 as i}from"./chunks/framework.CJQKpl5I.js";const b=JSON.parse('{"title":"第 5 章 国产硬件技术基础","description":"","frontmatter":{},"headers":[],"relativePath":"ch05_hardware.md","filePath":"ch05_hardware.md"}'),r={name:"ch05_hardware.md"};function e(h,t,o,n,u,P){return l(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="第-5-章-国产硬件技术基础" tabindex="-1">第 5 章 国产硬件技术基础 <a class="header-anchor" href="#第-5-章-国产硬件技术基础" aria-label="Permalink to &quot;第 5 章 国产硬件技术基础&quot;">​</a></h1><p>考核占比 10%。深入考察信创底层架构、技术路线选型与异构计算原理。</p><h2 id="_5-1-国产计算平台" tabindex="-1">5.1 国产计算平台 <a class="header-anchor" href="#_5-1-国产计算平台" aria-label="Permalink to &quot;5.1 国产计算平台&quot;">​</a></h2><h3 id="国产-cpu-路线" tabindex="-1">国产 CPU 路线 <a class="header-anchor" href="#国产-cpu-路线" aria-label="Permalink to &quot;国产 CPU 路线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>厂商</th><th>产品系列</th><th>指令集架构</th></tr></thead><tbody><tr><td>龙芯</td><td>龙芯 3A 系列</td><td>LoongArch</td></tr><tr><td>飞腾</td><td>飞腾系列</td><td>ARM</td></tr><tr><td>华为</td><td>鲲鹏系列</td><td>ARM</td></tr><tr><td>兆芯</td><td>开先、开胜系列</td><td>x86</td></tr><tr><td>海光</td><td>海光系列</td><td>x86</td></tr><tr><td>申威</td><td>申威系列</td><td>SW64</td></tr></tbody></table><ul><li>指令集体系主要分 x86、ARM、RISC-V、LoongArch</li><li>x86 生态兼容性最好，应用迁移成本低</li><li>ARM 以低功耗高性能著称，服务器和移动端广泛应用</li><li>RISC-V 开源免费，生态仍在发展</li></ul><h3 id="指令集与兼容性" tabindex="-1">指令集与兼容性 <a class="header-anchor" href="#指令集与兼容性" aria-label="Permalink to &quot;指令集与兼容性&quot;">​</a></h3><ul><li>ISA 定义处理器能理解的机器指令、寄存器等基本接口</li><li>不同 ISA 的机器指令编码不同</li><li>同一份 x86-64 二进制程序复制到 ARM64 系统后无法运行，核心原因是机器指令集面向不同 ISA</li><li>跨架构运行需要目标架构构建或重新编译</li></ul><h2 id="_5-2-兼容性层次" tabindex="-1">5.2 兼容性层次 <a class="header-anchor" href="#_5-2-兼容性层次" aria-label="Permalink to &quot;5.2 兼容性层次&quot;">​</a></h2><p>兼容性问题需要分层看待，从底层到上层依次为：</p><ul><li><p>ISA 指令集架构，机器指令的接口定义</p></li><li><p>API 应用程序接口，源码层面的调用约定</p></li><li><p>ABI 应用二进制接口，已编译二进制与运行库、系统接口之间的约定</p></li><li><p>运行库与依赖软件</p></li><li><p>启动机制</p></li><li><p>API 兼容说明源码可以重新编译通过，已编译二进制能否直接运行由 ABI 兼容性决定</p></li><li><p>API 兼容并自动保证 ABI 兼容</p></li><li><p>应用启动报缺少共享库，属于运行时依赖适配不完整</p></li><li><p>跨 CPU 架构迁移要解决机器指令和目标架构构建问题</p></li><li><p>动态链接程序能否运行受共享库架构和 ABI 兼容性影响</p></li></ul><h2 id="_5-3-异构计算" tabindex="-1">5.3 异构计算 <a class="header-anchor" href="#_5-3-异构计算" aria-label="Permalink to &quot;5.3 异构计算&quot;">​</a></h2><h3 id="计算单元定位" tabindex="-1">计算单元定位 <a class="header-anchor" href="#计算单元定位" aria-label="Permalink to &quot;计算单元定位&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>定位</th><th>特点</th></tr></thead><tbody><tr><td>CPU</td><td>通用计算，擅长复杂逻辑与任务调度</td><td>灵活，并行计算效率有限</td></tr><tr><td>GPU</td><td>大规模并行计算</td><td>并行强、生态成熟</td></tr><tr><td>NPU</td><td>神经网络专用加速</td><td>低功耗，适合本地运行</td></tr><tr><td>TPU</td><td>Google 专用 AI 处理器</td><td>针对 AI 和 Google 体系优化</td></tr><tr><td>ASIC</td><td>专用集成电路</td><td>效率高，成本高且不灵活</td></tr><tr><td>FPGA</td><td>可重构硬件</td><td>可重新配置，开发复杂</td></tr></tbody></table><ul><li>GPU 适合大量并行度高、计算密集的任务</li><li>NPU 面向神经网络等特定负载做专用加速</li><li>异构计算强调 CPU 与不同加速单元按任务特点协同配合</li><li>GPU 峰值算力高，任意程序在 GPU 上都一定比在 CPU 上运行得快，串行逻辑仍是 CPU 优势</li><li>算力指标 TFLOPS 表示每秒万亿次浮点运算</li></ul><h3 id="显存与带宽" tabindex="-1">显存与带宽 <a class="header-anchor" href="#显存与带宽" aria-label="Permalink to &quot;显存与带宽&quot;">​</a></h3><ul><li>HBM 高带宽内存通过 2.5D 封装与 GPU 直连，带宽可达数 TB/s</li><li>GDDR 带宽较低、成本低，用于消费级显卡</li><li>HBM 通过堆叠和 TSV 互连实现高带宽、低功耗，用于数据中心 GPU</li><li>显存容量决定能装载的模型参数和数据量</li><li>显存带宽决定数据读写速率，单位 GB/s 或 TB/s</li></ul><h2 id="_5-4-gpu-架构与-cuda" tabindex="-1">5.4 GPU 架构与 CUDA <a class="header-anchor" href="#_5-4-gpu-架构与-cuda" aria-label="Permalink to &quot;5.4 GPU 架构与 CUDA&quot;">​</a></h2><h3 id="gpu-硬件结构" tabindex="-1">GPU 硬件结构 <a class="header-anchor" href="#gpu-硬件结构" aria-label="Permalink to &quot;GPU 硬件结构&quot;">​</a></h3><ul><li>SM 流式多处理器是 GPU 核心计算单元，调度执行大量线程</li><li>Warp 线程束是基本调度单位，32 个线程为一组，同一时刻执行相同指令，即 SIMT 架构</li><li>CUDA Core 是通用计算单元</li><li>Tensor Core 是专用加速单元，加速矩阵乘加运算，是深度学习训练的关键</li><li>工艺节点影响性能与功耗平衡，7nm 是高端 AI GPU 的标志性节点</li></ul><h3 id="cuda-编程模型" tabindex="-1">CUDA 编程模型 <a class="header-anchor" href="#cuda-编程模型" aria-label="Permalink to &quot;CUDA 编程模型&quot;">​</a></h3><ul><li>CUDA 是 NVIDIA 2006 年推出的并行计算平台和编程模型，GPU 编程事实标准</li><li>线程组织分三级：Grid、Block、Thread</li><li>Kernel 核函数在 GPU 上并行执行，由 CPU 端调用启动</li><li>同一 warp 内线程执行不同分支时需串行，即 warp divergence，严重降低并行效率</li><li>shared memory 块内线程共享，延迟远低于全局显存</li><li>相邻线程访问相邻内存地址时合并为少量事务，提升带宽利用率</li><li>CUDA Stream 管理操作并发执行，不同 Stream 中的操作可并行</li><li>原子操作确保多线程对同一地址的并发操作无数据竞争</li></ul><h3 id="生态库" tabindex="-1">生态库 <a class="header-anchor" href="#生态库" aria-label="Permalink to &quot;生态库&quot;">​</a></h3><ul><li>cuBLAS 基础线性代数库，矩阵乘法等运算的底层基石</li><li>cuDNN 深度学习加速库，针对卷积、池化、归一化优化</li><li>TensorRT 高性能推理优化器，通过层融合、INT8/FP16 精度校准加速推理</li><li>NCCL 多 GPU 集合通信库，提供 AllReduce、Broadcast 等原语</li><li>PyTorch 等框架的分布式训练以集合通信库为底层后端</li></ul><h2 id="_5-5-天数智芯产品" tabindex="-1">5.5 天数智芯产品 <a class="header-anchor" href="#_5-5-天数智芯产品" aria-label="Permalink to &quot;5.5 天数智芯产品&quot;">​</a></h2><p>天数智芯是国产通用 GPU 供应商，产品线覆盖训练、推理、边端：</p><ul><li>天垓系列，训练产品。天垓100 为 2021 年发布的国内第一款全自研 GPU 架构云端训练芯片</li><li>智铠系列，推理产品。智铠100 于 2022 年发布，基于第二代通用 GPU 架构</li><li>彤央系列，边端产品</li></ul><table tabindex="0"><thead><tr><th>型号</th><th>内存</th><th>功耗</th><th>接口</th><th>定位</th></tr></thead><tbody><tr><td>天垓100（BI-V100）</td><td>32GB HBM2</td><td>250W</td><td>PCIe Gen4 x16</td><td>训练</td></tr><tr><td>天垓150</td><td>64GB HBM</td><td>350W</td><td>PCIe Gen4</td><td>训练，大模型</td></tr><tr><td>智铠100（MR-V100）</td><td>32GB HBM2E</td><td>150W</td><td>PCIe Gen4 x16</td><td>推理</td></tr><tr><td>智铠50（MR-V50）</td><td>16GB HBM2E</td><td>75W</td><td>PCIe Gen4 x16</td><td>推理</td></tr></tbody></table><ul><li>智铠系列支持 FP32、FP16、INT8 多精度推理混合计算</li><li>智铠支持最大 128 路视频解码，覆盖 H.264、H.265、VP9、AVS2 格式</li><li>智铠兼容 CUDA 生态，平均迁移时间较主流产品下降 50% 以上</li><li>天垓100 支持 200 余种人工智能模型，系统架构、指令集、核心算子、软件栈均自主研发</li></ul><h2 id="_5-6-液冷与散热技术" tabindex="-1">5.6 液冷与散热技术 <a class="header-anchor" href="#_5-6-液冷与散热技术" aria-label="Permalink to &quot;5.6 液冷与散热技术&quot;">​</a></h2><h3 id="液冷分类" tabindex="-1">液冷分类 <a class="header-anchor" href="#液冷分类" aria-label="Permalink to &quot;液冷分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>分类</th><th>原理</th><th>特点</th></tr></thead><tbody><tr><td>直接接触式</td><td>冷却液直接与芯片接触</td><td>热路径短、散热效率高，冷却液必须绝缘</td></tr><tr><td>间接接触式</td><td>冷却液流经冷板内部，经冷板导热</td><td>安全性高、兼容性好，使用常规冷却液</td></tr></tbody></table><ul><li>冷板液冷属于间接接触式液冷</li><li>冷板与芯片顶盖接触，通过热传导带走热量</li><li>常用冷却介质为去离子水或乙二醇水溶液</li><li>冷却液要求导热系数高、电导率低，普通自来水含杂质离子，适合直接使用</li><li>乙二醇可降低冰点防冻，导热系数低于纯水</li></ul><h3 id="系统组成" tabindex="-1">系统组成 <a class="header-anchor" href="#系统组成" aria-label="Permalink to &quot;系统组成&quot;">​</a></h3><ul><li>冷板液冷系统分三层：外部冷源、CDU 冷却液分配单元、冷板</li><li>CDU 负责冷却液分配与热量转移，内含循环泵、板式换热器、过滤器、膨胀罐、控制系统</li><li>工作回路为循环泵、分液器、快接头、冷板、回流</li><li>循环泵驱动冷却液流动，选型看流量、扬程、可靠性</li><li>快速接头支持在线维护，要求无滴漏</li><li>气液分离器排出气泡，漏液检测绳和传感器用于早期泄漏侦测</li></ul><h3 id="运维与故障" tabindex="-1">运维与故障 <a class="header-anchor" href="#运维与故障" aria-label="Permalink to &quot;运维与故障&quot;">​</a></h3><ul><li>首次启动或长停机重启，先查液位和管路密封性并充分排气</li><li>长停机时排空冷却液并干燥管路</li><li>漏液故障：关断对应阀门、定位、更换密封件</li><li>冷板堵塞导致效率下降：反向冲洗、更换冷板、加强过滤</li><li>泵故障：切换备用泵、排气、更换泵</li><li>冷却液中断或大量气泡聚集，最直接风险是热击穿</li><li>导热硅脂涂覆均匀最佳，过厚增加热阻</li><li>冷板安装按对角线顺序逐步均匀拧紧</li></ul><h3 id="液冷与-ai-算力" tabindex="-1">液冷与 AI 算力 <a class="header-anchor" href="#液冷与-ai-算力" aria-label="Permalink to &quot;液冷与 AI 算力&quot;">​</a></h3><ul><li>液冷支持 500W 以上高功耗芯片，散热能力优于风冷</li><li>液冷降低 PUE、支持更高密度部署、降低噪音</li><li>液冷优势在于提升持续算力释放，避免高功耗 GPU 过热</li><li>液冷系统仍需定期检查维护</li></ul><h2 id="_5-7-大模型训练集群" tabindex="-1">5.7 大模型训练集群 <a class="header-anchor" href="#_5-7-大模型训练集群" aria-label="Permalink to &quot;5.7 大模型训练集群&quot;">​</a></h2><h3 id="并行策略与通信" tabindex="-1">并行策略与通信 <a class="header-anchor" href="#并行策略与通信" aria-label="Permalink to &quot;并行策略与通信&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>切分方式</th><th>通信特征</th><th>适用场景</th></tr></thead><tbody><tr><td>数据并行</td><td>每卡完整模型，不同数据批次</td><td>梯度同步通信量大</td><td>模型能装入单卡</td></tr><tr><td>模型并行</td><td>模型层切分到不同 GPU</td><td>通信中等</td><td>超大模型</td></tr><tr><td>流水线并行</td><td>按层分段处理</td><td>段间传递开销小</td><td>深度模型</td></tr><tr><td>张量并行</td><td>单层参数切分到多 GPU</td><td>通信频率极高</td><td>大模型、MoE</td></tr></tbody></table><ul><li>通信带宽不足影响所有并行策略</li><li>高速互联方案：InfiniBand 400G 以上为高性能首选，RoCE 100G/200G 为性价比方案</li><li>GPU 间通信依赖高速互联网络</li><li>大模型训练以混合精度为主，权重 FP32 存储、FP16 计算</li></ul><h2 id="_5-8-国产加速芯片生态" tabindex="-1">5.8 国产加速芯片生态 <a class="header-anchor" href="#_5-8-国产加速芯片生态" aria-label="Permalink to &quot;5.8 国产加速芯片生态&quot;">​</a></h2><p>国产 AI 加速芯片形成多条技术路线，定位各有侧重：</p><table tabindex="0"><thead><tr><th>厂商</th><th>产品</th><th>架构路线</th><th>定位</th></tr></thead><tbody><tr><td>天数智芯</td><td>天垓、智铠</td><td>通用 GPU</td><td>训练与推理，兼容 CUDA 生态</td></tr><tr><td>华为昇腾</td><td>昇腾 310、910</td><td>自研达芬奇架构</td><td>NPU，训练推理全栈，配 CANN 软件栈</td></tr><tr><td>寒武纪</td><td>思元系列</td><td>自研 NPU</td><td>云端与边缘智能加速</td></tr><tr><td>摩尔线程</td><td>苏堤、春晓</td><td>通用 GPU</td><td>兼容 CUDA 生态，图形与计算</td></tr><tr><td>景嘉微</td><td>JM 系列</td><td>GPU</td><td>图形处理，自主指令集</td></tr></tbody></table><ul><li>技术路线分通用 GPU 与专用 NPU 两大类，通用 GPU 兼容性好，专用 NPU 能效高</li><li>国产芯片普遍配套自研软件栈，例如昇腾 CANN、天数智算软件栈</li><li>软件生态决定应用迁移成本，兼容 CUDA 生态的芯片迁移成本低</li><li>训推组合能力指同一厂商同时提供训练芯片与推理芯片，天数智芯具备云边协同和训推组合全方案</li><li>选型时考虑算力、显存、生态兼容、功耗和成本等因素</li></ul>',47)])])}const s=d(r,[["render",e]]);export{b as __pageData,s as default};
